SELECT p.PurchaseOrderID,l.PurchaseOrderLineID,l.StockItemID,p.SupplierID,p.ExpectedDeliveryDate,l.LastReceiptDate,l.OrderedOuters,l.ReceivedOuters,l.IsOrderLineFinalized,l.LastReceiptDate>p.ExpectedDeliveryDate AS LaterCalendarDate FROM raw.Purchasing_PurchaseOrders p JOIN raw.Purchasing_PurchaseOrderLines l USING(PurchaseOrderID) WHERE l.LastReceiptDate IS NOT NULL ORDER BY LaterCalendarDate DESC,l.PurchaseOrderLineID LIMIT 20